/**
 * @yaks/id — entity ids for a yaks graph: the eid a client generates, and the
 * human id a person types.
 *
 * ## Two ids, one entity
 * An entity's durable identity is its **eid** — a UUID, generated by whoever
 * creates the entity (@yaks/graph `mint`), so a write never waits for the store
 * to assign an id. A UUID is not something a person can read or type, so an
 * entity also has a **human id**: a letter and a number, `B-7`. The number is
 * this package's; the letter comes from the vocabulary.
 *
 * ## The `prefix` of a kind
 * The letter is a kind's `prefix` (@yaks/vocab): a kind that declares
 * `"prefix": "B"` numbers its entities in the `B` series. On a component it
 * makes the component the kind of its own name:
 *
 * ```json
 * { "$defs": { "book": { "component": true, "prefix": "B", "properties": {} } } }
 * ```
 *
 * Load the vocabulary and the ids follow:
 *
 * ```ts
 * import { assertEquals } from '@std/assert'
 * import { mint } from '@yaks/graph'
 * import { loadVocab } from '@yaks/vocab'
 * import { idKeywords, idOf, parse } from '@yaks/id'
 *
 * let book = { component: true, kind: true, prefix: 'B', properties: {} }
 * let v = loadVocab([{ $defs: { book } }], [idKeywords])
 * let id = idOf(v)
 *
 * assertEquals(id({ eid: mint(), kind: 'book', num: 7, prefix: 'B' }), 'B-7')
 * let eid = 'a3f19c02-4b00-4000-8000-000000000001'
 * assertEquals(id({ eid, kind: 'book' }), '#a3f19c024b')
 * assertEquals(parse('B-7'), { prefix: 'B', num: 7 })
 * // a bare number parses, and names an entity while only one holds it
 * assertEquals(parse('7'), { prefix: '', num: 7 })
 * ```
 *
 * The letter and the number together name an entity: `B-7` and `A-7` are two.
 * A bare `7` names one while only one holds that number. An entity whose
 * components declare no prefix is not numbered, and shows its short handle.
 *
 * ## Numbers are opt in A graph has numbers because it loaded this package's
 * plugin, and not otherwise. `@yaks/id/vocab` adds the `num` property to the
 * `entity` row, and `@yaks/id/graph` carries the two plugins that use it:
 * `numbers()`, which answers `$num: true` on a bundle by allocating one, and
 * `ids()`, which resolves the `B-7` a person typed back to an eid. A graph that
 * registers neither stores no number, displays none, and refuses `$num` as a
 * request it has no plugin for.
 *
 * The pieces:
 * - `keywords.ts` — the `$vocabulary` URI of ids, ready to register
 * - `id.ts` — the prefix table, `(prefix, num)` → id and back, and the short
 *   handle an entity shows before it has been numbered
 * - `vocab.ts` — `entity{num}`, the property the number is kept in
 * - `number.ts`, `ids.ts` — the two graph plugins, re-exported from `./graph`
 *
 * @module
 */

export * from './keywords.ts'
export * from './id.ts'
export { idDoc } from './vocab.ts'
